.input-btn-plus svg,
.input-btn-plus i,
.input-btn-plus span,
.input-btn-mic img,
.input-btn-mic svg,
.input-btn-mic i,
.input-btn-mic span,
.input-btn-sticker img,
.input-btn-sticker svg,
.input-btn-sticker i,
.input-btn-sticker span,
.input-btn-ai img,
.input-btn-ai svg,
.input-btn-ai i,
.input-btn-ai span,
.send-btn-custom img,
.send-btn-custom svg,
.send-btn-custom i,
.send-btn-custom span,
.stop-btn-custom img,
.stop-btn-custom svg,
.stop-btn-custom i,
.stop-btn-custom span {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
}

/* 可选：如果您想让按钮本身完全透明但保留点击区域，可以添加这一行 */
.input-btn-plus,
.input-btn-mic,
.input-btn-sticker,
.input-btn-ai,
.send-btn-custom,
.stop-btn-custom {
  color: transparent !important;
  font-size: 0 !important;
}

/* 
 * ============================================
