}

/* 按钮4: AI */
.input-btn-ai { 
  left: 58%;
  bottom: -40px;
}

/* 按钮5: 发送/停止 */
.send-btn-custom,
.stop-btn-custom { 
  left: 90%;
  bottom: -40px;
}


